const COURSE_LESSON_HTML = {
  "kurssArticlesLesson": "\n  <h3>Lidwoorden</h3>\n\n  <div class=\"artikuli-info artikuli-intro-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Het Duitse lidwoord komt niet altijd overeen met het lidwoord (de/het) of het geslacht van het woord in het Nederlands. Leer zelfstandige naamwoorden daarom het best samen met hun lidwoord.</div>\n  </div>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>•</span>Voorbeelden van lidwoorden</h4>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">der Tisch — tafel</div>\n      <div class=\"kurss-example\">die Tür — deur</div>\n      <div class=\"kurss-example\">das Messer — mes</div>\n      <div class=\"kurss-example\">das Mädchen — meisje</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>♂</span>Vaak DER</h4>\n    <p class=\"artikuli-explain\">DER wordt vaak gebruikt voor mannelijke personen, dagen, maanden, seizoenen en sommige woorden met bepaalde uitgangen.</p>\n\n    <h5 class=\"artikuli-subtitle\">Regels</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-er → vaak DER, bijvoorbeeld: der Computer, der Lehrer <span class=\"artikuli-note\">maar niet altijd</span></div>\n      <div class=\"kurss-example\">-ling → vaak DER, bijvoorbeeld: der Schmetterling</div>\n      <div class=\"kurss-example\">-ismus → vaak DER, bijvoorbeeld: der Tourismus, der Kapitalismus</div>\n      <div class=\"kurss-example\">mannelijke personen → der Mann, der Vater</div>\n      <div class=\"kurss-example\">beroepen → der Lehrer, der Arzt</div>\n      <div class=\"kurss-example\">automerken → der BMW, der Mercedes</div>\n      <div class=\"kurss-example\">dagen → der Montag, der Dienstag</div>\n      <div class=\"kurss-example\">maanden → der August, der Dezember</div>\n      <div class=\"kurss-example\">seizoenen → der Sommer, der Winter</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Voorbeelden</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">der Mann — man</div>\n      <div class=\"kurss-example\">der Vater — vader</div>\n      <div class=\"kurss-example\">der Montag — maandag</div>\n      <div class=\"kurss-example\">der August — augustus</div>\n      <div class=\"kurss-example\">der Sommer — zomer</div>\n      <div class=\"kurss-example\">der Lehrer — leraar</div>\n      <div class=\"kurss-example\">der Computer — computer</div>\n      <div class=\"kurss-example\">der Schmetterling — vlinder</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>♀</span>Vaak DIE</h4>\n    <p class=\"artikuli-explain\">DIE wordt vaak gebruikt voor vrouwelijke personen, het meervoud en woorden met de uitgangen -ung, -heit, -keit, -schaft, -ion, -tät, -ei.</p>\n\n    <h5 class=\"artikuli-subtitle\">Regels</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-ung → die Wohnung, die Rechnung</div>\n      <div class=\"kurss-example\">-heit → die Freiheit, die Gesundheit</div>\n      <div class=\"kurss-example\">-keit → die Möglichkeit</div>\n      <div class=\"kurss-example\">-schaft → die Mannschaft</div>\n      <div class=\"kurss-example\">-ion → die Nation</div>\n      <div class=\"kurss-example\">-tät → die Universität</div>\n      <div class=\"kurss-example\">-ei → die Polizei, die Bäckerei</div>\n      <div class=\"kurss-example\">vrouwelijke personen → die Frau, die Mutter</div>\n      <div class=\"kurss-example\">motormerken → die Harley-Davidson, die Yamaha</div>\n      <div class=\"kurss-example\">meervoud → die Autos, die Häuser</div>\n      <div class=\"kurss-example\">meervoud bijna altijd → die Autos, die Häuser, die Kinder</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Voorbeelden</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">die Frau — vrouw</div>\n      <div class=\"kurss-example\">die Mutter — moeder</div>\n      <div class=\"kurss-example\">die Wohnung — woning / appartement</div>\n      <div class=\"kurss-example\">die Rechnung — rekening</div>\n      <div class=\"kurss-example\">die Freiheit — vrijheid</div>\n      <div class=\"kurss-example\">die Möglichkeit — mogelijkheid</div>\n      <div class=\"kurss-example\">die Mannschaft — team / ploeg</div>\n      <div class=\"kurss-example\">die Nation — natie</div>\n      <div class=\"kurss-example\">die Universität — universiteit</div>\n      <div class=\"kurss-example\">die Polizei — politie</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>◇</span>Vaak DAS</h4>\n    <p class=\"artikuli-explain\">DAS wordt vaak gebruikt voor verkleinwoorden op -chen / -lein, veel woorden op -ment / -um en werkwoorden die als zelfstandig naamwoord worden gebruikt.</p>\n\n    <h5 class=\"artikuli-subtitle\">Regels</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-chen → das Mädchen, das Häuschen</div>\n      <div class=\"kurss-example\">-lein → das Fräulein</div>\n      <div class=\"kurss-example\">-ment → das Instrument</div>\n      <div class=\"kurss-example\">-um → das Zentrum, das Museum</div>\n      <div class=\"kurss-example\">metalen → das Gold, das Silber, das Eisen</div>\n      <div class=\"kurss-example\">scheikundige elementen → das Eisen, das Kupfer</div>\n      <div class=\"kurss-example\">hotels → das Hotel</div>\n      <div class=\"kurss-example\">kleuren als zelfstandig naamwoord → das Rot, das Blau</div>\n      <div class=\"kurss-example\">werkwoord als zelfstandig naamwoord → das Essen, das Lernen</div>\n      <div class=\"kurss-example\">werkwoorden als zelfstandig naamwoord → das Essen, das Lernen, das Lesen</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Voorbeelden</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">das Kind — kind</div>\n      <div class=\"kurss-example\">das Mädchen — meisje</div>\n      <div class=\"kurss-example\">das Häuschen — huisje</div>\n      <div class=\"kurss-example\">das Instrument — instrument</div>\n      <div class=\"kurss-example\">das Zentrum — centrum</div>\n      <div class=\"kurss-example\">das Museum — museum</div>\n      <div class=\"kurss-example\">das Essen — het eten / maaltijd</div>\n      <div class=\"kurss-example\">das Lernen — het leren</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>!</span>Belangrijke uitzonderingen / leren met het lidwoord</h4>\n    <p class=\"artikuli-explain\">Bij sommige woorden kun je het lidwoord niet betrouwbaar afleiden uit de uitgang of uit het Nederlandse lidwoord (de/het). Leer ze het best samen met hun lidwoord.</p>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">die Tür — deur</div>\n      <div class=\"kurss-example\">das Messer — mes</div>\n      <div class=\"kurss-example\">die Sonne — zon</div>\n      <div class=\"kurss-example\">der Mond — maan</div>\n      <div class=\"kurss-example\">das Mädchen — meisje</div>\n      <div class=\"kurss-example\">das Auto — auto</div>\n      <div class=\"kurss-example\">der Käse — kaas</div>\n      <div class=\"kurss-example\">die Gabel — vork</div>\n    </div>\n  </section>\n\n  <div class=\"artikuli-info artikuli-bottom-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Uitgangen en woordgroepen helpen je het lidwoord te raden, maar ze zijn geen 100% zekere regel. Twijfel je? Leer het woord dan samen met het lidwoord.</div>\n  </div>\n",
  "kurssPronounsLesson": "\n  <h3>Voornaamwoorden</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Nominativ, Akkusativ en Dativ — vormen van de voornaamwoorden.</div>\n  </div>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>N</span>Nominativ — wie/wat?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich — ik</div><div class=\"kurss-example\">du — jij</div><div class=\"kurss-example\">er — hij</div><div class=\"kurss-example\">sie — zij</div><div class=\"kurss-example\">es — het</div><div class=\"kurss-example\">wir — wij</div><div class=\"kurss-example\">ihr — jullie</div><div class=\"kurss-example\">sie — zij</div><div class=\"kurss-example\">Sie — u (beleefd)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>A</span>Akkusativ — wie/wat?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">mich — mij</div><div class=\"kurss-example\">dich — jou</div><div class=\"kurss-example\">ihn — hem (m.)</div><div class=\"kurss-example\">sie — haar (v.)</div><div class=\"kurss-example\">es — het</div><div class=\"kurss-example\">uns — ons</div><div class=\"kurss-example\">euch — jullie</div><div class=\"kurss-example\">sie — hen</div><div class=\"kurss-example\">Sie — u (beleefd)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>D</span>Dativ — aan wie?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">mir — (aan) mij</div><div class=\"kurss-example\">dir — (aan) jou</div><div class=\"kurss-example\">ihm — (aan) hem</div><div class=\"kurss-example\">ihr — (aan) haar</div><div class=\"kurss-example\">uns — (aan) ons</div><div class=\"kurss-example\">euch — (aan) jullie</div><div class=\"kurss-example\">ihnen — (aan) hen</div><div class=\"kurss-example\">Ihnen — (aan) u (beleefd)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>?</span>Hoe kies je de juiste vorm?</h4>\n    <ul class=\"kurss-summary-list\"><li><span class=\"case-blue\">Nominativ</span> — onderwerp (wie doet iets?)</li><li><span class=\"case-red\">Akkusativ</span> — lijdend voorwerp (wie/wat?)</li><li><span class=\"case-green\">Dativ</span> — meewerkend voorwerp (aan wie?)</li></ul>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>•</span>Voorbeelden</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">Ich sehe <span class=\"case-red\">dich</span>. — Ik zie je.</div><div class=\"kurss-example\">Ich sehe <span class=\"case-red\">ihn</span>. — Ik zie hem.</div><div class=\"kurss-example\">Wir mögen <span class=\"case-red\">euch</span>. — We vinden jullie aardig.</div><div class=\"kurss-example\">Ich helfe <span class=\"case-green\">dir</span>. — Ik help je.</div><div class=\"kurss-example\">Ich gebe <span class=\"case-green\">ihm</span> ein Buch. — Ik geef hem een boek.</div><div class=\"kurss-example\">Wir danken <span class=\"case-green\">euch</span>. — We bedanken jullie.</div></div>\n  </section>\n\n  <div class=\"artikuli-info artikuli-bottom-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Nominativ is altijd het onderwerp van de zin, Akkusativ en Dativ zijn voorwerpen. Kijk naar het werkwoord en vraag: <span class=\"case-red\">wie/wat?</span> of <span class=\"case-green\">aan wie?</span></div>\n  </div>\n",
  "kurssPronunciationLesson": "\n            <h3>Klinkers — lang en kort</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n              <span class=\"artikuli-info-icon\">i</span>\n              <div>In het Duits kunnen klinkers lang of kort zijn. Dat beïnvloedt de uitspraak van het woord.</div>\n            </div>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Lange klinker</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">warm (warm) — warm</div><div class=\"kurss-example\">gut (goet) — goed</div><div class=\"kurss-example\">Tat (taat) — daad / handeling</div><div class=\"kurss-example\">Flur (floer) — gang / hal</div><div class=\"kurss-example\">Weg (week) — weg</div><div class=\"kurss-example\">Hut (hoet) — hoed</div><div class=\"kurss-example\">Hof (hoof) — binnenplaats / erf</div><div class=\"kurss-example\">Schlaf (sjlaaf) — slaap</div></div>\n              <p class=\"artikuli-explain\">Als er na de klinker één medeklinker volgt, wordt de klinker vaak lang uitgesproken.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Korte klinker</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Pilz (pilts) — paddenstoel</div><div class=\"kurss-example\">Wort (wort) — woord</div><div class=\"kurss-example\">Mund (moent) — mond</div><div class=\"kurss-example\">bald (balt) — binnenkort / gauw</div><div class=\"kurss-example\">scharf (sjarf) — scherp</div><div class=\"kurss-example\">Feld (felt) — veld</div><div class=\"kurss-example\">voll (fol) — vol</div></div>\n              <p class=\"artikuli-explain\">Als er na de klinker twee of meer medeklinkers volgen, wordt de klinker vaak kort uitgesproken.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Uitgangen en / el / er</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">singen (zingen) — zingen</div><div class=\"kurss-example\">tragen (traagen) — dragen</div><div class=\"kurss-example\">Garten (garten) — tuin</div><div class=\"kurss-example\">Vogel (foogel) — vogel</div><div class=\"kurss-example\">Segel (zeegel) — zeil</div><div class=\"kurss-example\">Braten (braaten) — gebraad</div><div class=\"kurss-example\">Bogen (boogen) — boog</div><div class=\"kurss-example\">Spiegel (sjpiegel) — spiegel</div><div class=\"kurss-example\">Finger (finger) — vinger</div><div class=\"kurss-example\">Halter (halter) — houder</div><div class=\"kurss-example\">Arbeiter (arbaiter) — arbeider</div><div class=\"kurss-example\">Häuser (hoizer) — huizen</div><div class=\"kurss-example\">wieder (wieder) — weer / opnieuw</div><div class=\"kurss-example\">breiter (braiter) — breder</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>De letter h als lengteteken</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Rahmen (raamen) — lijst / kader</div><div class=\"kurss-example\">Ohr (oor) — oor</div><div class=\"kurss-example\">Kohle (koole) — steenkool / kolen</div><div class=\"kurss-example\">Zahl (tsaal) — getal</div><div class=\"kurss-example\">ihn (ien) — hem</div><div class=\"kurss-example\">ihm (iem) — (aan) hem</div><div class=\"kurss-example\">Huhn (hoen) — kip</div><div class=\"kurss-example\">nahm (naam) — nam</div><div class=\"kurss-example\">nehmen (neemen) — nemen</div><div class=\"kurss-example\">Schuh (sjoe) — schoen</div></div>\n              <p class=\"artikuli-explain\">In sommige woorden verlengt h de voorafgaande klinker. In zulke gevallen wordt de h meestal niet uitgesproken.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Uitgangen op e</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Lampe (lampe) — lamp</div><div class=\"kurss-example\">Hase (haaze) — haas</div><div class=\"kurss-example\">Knabe (knaabe) — jongen</div><div class=\"kurss-example\">Rabe (raabe) — raaf</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Lange i = ie</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">die (die) — lidwoord “die”</div><div class=\"kurss-example\">diese (dieze) — deze</div><div class=\"kurss-example\">wieder (wieder) — weer / opnieuw</div><div class=\"kurss-example\">Fliege (fliege) — vlieg</div><div class=\"kurss-example\">Ziege (tsiege) — geit</div><div class=\"kurss-example\">Stiel (sjtiel) — steel</div><div class=\"kurss-example\">Dieb (diep) — dief</div><div class=\"kurss-example\">hier (hier) — hier</div></div>\n              <p class=\"artikuli-explain\">De lange i wordt in het Duits vaak geschreven als ie.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Dubbele klinkers</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Saal (zaal) — zaal</div><div class=\"kurss-example\">Saat (zaat) — zaad / zaaiing</div><div class=\"kurss-example\">Staat (sjtaat) — staat</div><div class=\"kurss-example\">Beere (beere) — bes</div><div class=\"kurss-example\">See (zee) — meer / zee</div><div class=\"kurss-example\">Beet (beet) — perk / bed</div><div class=\"kurss-example\">Boot (boot) — boot</div><div class=\"kurss-example\">Moor (moor) — veen / moeras</div><div class=\"kurss-example\">Moos (moos) — mos</div></div>\n              <p class=\"artikuli-explain\">Dubbele klinkers worden meestal lang uitgesproken.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>ä</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Wand (want) — wand / muur</div><div class=\"kurss-example\">Wände (wende) — wanden / muren</div><div class=\"kurss-example\">Vater (faater) — vader</div><div class=\"kurss-example\">Väter (feeter) — vaders</div><div class=\"kurss-example\">Schrank (sjrank) — kast</div><div class=\"kurss-example\">Schränke (sjrenke) — kasten</div><div class=\"kurss-example\">Bank (bank) — bank / zitbank</div><div class=\"kurss-example\">Bänke (benke) — zitbanken</div><div class=\"kurss-example\">Tal (taal) — dal</div><div class=\"kurss-example\">Täler (teeler) — dalen</div></div>\n              <p class=\"artikuli-explain\">ä is de umlaut van a.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>ö</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Rose (rooze) — roos</div><div class=\"kurss-example\">Röschen (reuschen) — roosje</div><div class=\"kurss-example\">Ofen (oofen) — oven / kachel</div><div class=\"kurss-example\">Öfen (eufen) — ovens / kachels</div><div class=\"kurss-example\">Rock (rok) — rok</div><div class=\"kurss-example\">Röcke (reuke) — rokken</div></div>\n              <p class=\"artikuli-explain\">ö is de umlaut van o.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>ü</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">kurz (koerts) — kort</div><div class=\"kurss-example\">kürzer (kurtser) — korter</div><div class=\"kurss-example\">Kunst (koenst) — kunst</div><div class=\"kurss-example\">Künste (kunste) — kunsten</div><div class=\"kurss-example\">Mutter (moeter) — moeder</div><div class=\"kurss-example\">Mütter (mutter) — moeders</div></div>\n              <p class=\"artikuli-explain\">ü is de umlaut van u.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Tweeklanken: äu</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Baum (baum) — boom</div><div class=\"kurss-example\">Bäume (boime) — bomen</div><div class=\"kurss-example\">Haus (haus) — huis</div><div class=\"kurss-example\">Häuser (hoizer) — huizen</div><div class=\"kurss-example\">Strauch (sjtrauch) — struik</div><div class=\"kurss-example\">Sträucher (sjtroicher) — struiken</div><div class=\"kurss-example\">Maus (maus) — muis</div><div class=\"kurss-example\">Mäuse (moize) — muizen</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Tweeklanken: eu</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">heute (hoite) — vandaag</div><div class=\"kurss-example\">Leute (loite) — mensen</div><div class=\"kurss-example\">neu (noi) — nieuw</div><div class=\"kurss-example\">neun (noin) — negen</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Tweeklanken: ei</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">mein (main) — mijn</div><div class=\"kurss-example\">dein (dain) — jouw</div><div class=\"kurss-example\">sein (zain) — zijn (van hem) / zijn (werkwoord)</div><div class=\"kurss-example\">frei (frai) — vrij</div><div class=\"kurss-example\">arbeiten (arbaiten) — werken</div></div>\n            </section>\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>✓</span>Uitspraakopmerkingen bij les 2</h4>\n              <ul class=\"kurss-summary-list\"><li>in de woorden ich, nicht, rechnen, zeichnen wordt “ch” zacht uitgesproken (als een zachte “g”, zoals in het Zuid-Nederlands en Vlaams)</li><li>in de woorden arbeiten en zeichnen wordt “ei” uitgesproken als “ai”</li><li>“sp” aan het begin van een woord klinkt als “sjp”</li><li>in het werkwoord tun wordt de “u” lang uitgesproken (als een lange “oe”)</li></ul>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>✓</span>Samenvatting</h4>\n              <ul class=\"kurss-summary-list\"><li>één medeklinker na de klinker → vaak lange klinker</li><li>twee of meer medeklinkers → vaak korte klinker</li><li>h kan de klinker verlengen</li><li>ie betekent vaak een lange i</li><li>dubbele klinkers zijn meestal lang</li></ul>\n            </section>",
  "kurssConsonantsLesson": "\n            <h3>Medeklinkers en lettercombinaties</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n              <span class=\"artikuli-info-icon\">i</span>\n              <div>In het Duits worden sommige medeklinkers en lettercombinaties anders uitgesproken dan ze geschreven worden. In deze les staan de belangrijkste voorbeelden voor beginners.</div>\n            </div>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Medeklinkers</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">das Rad (das raat) — wiel</div><div class=\"kurss-example\">die Räder (die reeder) — wielen</div><div class=\"kurss-example\">Bad (baat) — bad / badkamer</div><div class=\"kurss-example\">Bäder (beeder) — baden / badkamers</div></div>\n              <p class=\"artikuli-explain\">Aan het eind van een woord worden medeklinkers vaak niet uitgesproken zoals ze geschreven worden.</p>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>ch</h4>\n              <p class=\"artikuli-explain\">“ch” kan zacht of hard klinken. In sommige woorden klinkt het als een zachte “g” (zoals in het Zuid-Nederlands en Vlaams), in andere als de harde Nederlandse “ch” in “lachen”.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">rechnen (rechnen) — rekenen</div><div class=\"kurss-example\">zeichnen (tsaichnen) — tekenen</div><div class=\"kurss-example\">nicht (nicht) — niet</div><div class=\"kurss-example\">schlecht (sjlecht) — slecht</div><div class=\"kurss-example\">mich (mich) — mij</div><div class=\"kurss-example\">dich (dich) — jou</div><div class=\"kurss-example\">Strauch (sjtrauch) — struik</div><div class=\"kurss-example\">noch (noch) — nog</div><div class=\"kurss-example\">Nacht (nacht) — nacht</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>sch</h4>\n              <p class=\"artikuli-explain\">“sch” wordt in het Duits uitgesproken als “sj” (zoals in het Nederlandse “sjaal”), dus niet als “s” + “ch” zoals in het Nederlands.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Schule (sjoele) — school</div><div class=\"kurss-example\">Schüler (sjuuler) — leerling / scholier</div><div class=\"kurss-example\">Schiff (sjif) — schip</div><div class=\"kurss-example\">Schraube (sjraube) — schroef</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>sp en st aan het begin van een woord</h4>\n              <p class=\"artikuli-explain\">Aan het begin van een woord of lettergreep wordt “sp” vaak uitgesproken als “sjp” en “st” als “sjt”.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">spielen (sjpielen) — spelen</div><div class=\"kurss-example\">Sprung (sjproeng) — sprong</div><div class=\"kurss-example\">stehen (sjtee-en) — staan</div><div class=\"kurss-example\">Stall (sjtal) — stal</div><div class=\"kurss-example\">Stand (sjtant) — stand / positie</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>qu</h4>\n              <p class=\"artikuli-explain\">“qu” wordt in het Duits meestal uitgesproken als “kw”.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Qual (kwaal) — kwelling</div><div class=\"kurss-example\">Quartier (kwartier) — onderkomen / wijk</div><div class=\"kurss-example\">quer (kweer) — dwars</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>s en z</h4>\n              <p class=\"artikuli-explain\">Aan het begin van een woord klinkt “s” vaak als “z”. De letter “z” klinkt in het Duits als “ts”.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">sagen (zaagen) — zeggen</div><div class=\"kurss-example\">singen (zingen) — zingen</div><div class=\"kurss-example\">Rose (rooze) — roos</div><div class=\"kurss-example\">Zahl (tsaal) — getal</div><div class=\"kurss-example\">Zeit (tsait) — tijd</div><div class=\"kurss-example\">Zink (tsink) — zink</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>v</h4>\n              <p class=\"artikuli-explain\">In het Duits wordt “v” vaak uitgesproken als “f”. In leenwoorden klinkt het vaak als een stemhebbende “v”, bijna als de Nederlandse “w”.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Vater (faater) — vader</div><div class=\"kurss-example\">von (fon) — van</div><div class=\"kurss-example\">viel (fiel) — veel</div><div class=\"kurss-example\">vier (fier) — vier</div><div class=\"kurss-example\">Villa (willa) — villa</div><div class=\"kurss-example\">Klavier (klawier) — piano</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>x en y</h4>\n              <p class=\"artikuli-explain\">“x” wordt uitgesproken als “ks”. “y” wordt in sommige woorden uitgesproken als “ü” (zoals de Nederlandse “u” / “uu”).</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Felix (feeliks) — Felix</div><div class=\"kurss-example\">Axt (akst) — bijl</div><div class=\"kurss-example\">Mystik (mustik) — mystiek</div><div class=\"kurss-example\">Mythe (muute) — mythe</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>ß</h4>\n              <p class=\"artikuli-explain\">“ß” wordt in het Duits uitgesproken als “s”.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Fuß (foes) — voet</div><div class=\"kurss-example\">Füße (fuuse) — voeten</div><div class=\"kurss-example\">Grüße (gruuse) — groeten</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>✓</span>Samenvatting</h4>\n              <ul class=\"kurss-summary-list\"><li>sch → sj</li><li>sp / st aan het begin → sjp / sjt</li><li>qu → kw</li><li>z → ts</li><li>v vaak → f</li><li>x → ks</li><li>ß → s</li></ul>\n            </section>",
  "kurssVerbBasicsLesson": "\n            <h3>Basis van werkwoorden</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n              <span class=\"artikuli-info-icon\">i</span>\n              <div>Werkwoorden uit les 1 en hun vervoeging.</div>\n            </div>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Werkwoorden</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">kommen — komen</div><div class=\"kurss-example\">gehen — gaan</div><div class=\"kurss-example\">stehen — staan</div><div class=\"kurss-example\">singen — zingen</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>kommen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich komme — ik kom</div><div class=\"kurss-example\">du kommst — jij komt</div><div class=\"kurss-example\">er kommt — hij komt</div><div class=\"kurss-example\">sie kommt — zij komt</div><div class=\"kurss-example\">wir kommen — wij komen</div><div class=\"kurss-example\">ihr kommt — jullie komen</div><div class=\"kurss-example\">sie kommen — zij komen</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>gehen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich gehe — ik ga</div><div class=\"kurss-example\">du gehst — jij gaat</div><div class=\"kurss-example\">er geht — hij gaat</div><div class=\"kurss-example\">sie geht — zij gaat</div><div class=\"kurss-example\">wir gehen — wij gaan</div><div class=\"kurss-example\">ihr geht — jullie gaan</div><div class=\"kurss-example\">sie gehen — zij gaan</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>stehen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich stehe — ik sta</div><div class=\"kurss-example\">du stehst — jij staat</div><div class=\"kurss-example\">er steht — hij staat</div><div class=\"kurss-example\">sie steht — zij staat</div><div class=\"kurss-example\">wir stehen — wij staan</div><div class=\"kurss-example\">ihr steht — jullie staan</div><div class=\"kurss-example\">sie stehen — zij staan</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>singen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich singe — ik zing</div><div class=\"kurss-example\">du singst — jij zingt</div><div class=\"kurss-example\">er singt — hij zingt</div><div class=\"kurss-example\">sie singt — zij zingt</div><div class=\"kurss-example\">wir singen — wij zingen</div><div class=\"kurss-example\">ihr singt — jullie zingen</div><div class=\"kurss-example\">sie singen — zij zingen</div></div>\n            </section>\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Werkwoorden uit les 2</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">spielen — spelen</div><div class=\"kurss-example\">arbeiten — werken</div><div class=\"kurss-example\">fragen — vragen</div><div class=\"kurss-example\">antworten — antwoorden</div><div class=\"kurss-example\">rechnen — rekenen</div><div class=\"kurss-example\">zeichnen — tekenen</div><div class=\"kurss-example\">tun — doen</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>spielen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich spiele — ik speel</div><div class=\"kurss-example\">du spielst — jij speelt</div><div class=\"kurss-example\">er spielt — hij speelt</div><div class=\"kurss-example\">sie spielt — zij speelt</div><div class=\"kurss-example\">wir spielen — wij spelen</div><div class=\"kurss-example\">ihr spielt — jullie spelen</div><div class=\"kurss-example\">sie spielen — zij spelen</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>arbeiten</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich arbeite — ik werk</div><div class=\"kurss-example\">du arbeitest — jij werkt</div><div class=\"kurss-example\">er arbeitet — hij werkt</div><div class=\"kurss-example\">sie arbeitet — zij werkt</div><div class=\"kurss-example\">wir arbeiten — wij werken</div><div class=\"kurss-example\">ihr arbeitet — jullie werken</div><div class=\"kurss-example\">sie arbeiten — zij werken</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>fragen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich frage — ik vraag</div><div class=\"kurss-example\">du fragst — jij vraagt</div><div class=\"kurss-example\">er fragt — hij vraagt</div><div class=\"kurss-example\">sie fragt — zij vraagt</div><div class=\"kurss-example\">wir fragen — wij vragen</div><div class=\"kurss-example\">ihr fragt — jullie vragen</div><div class=\"kurss-example\">sie fragen — zij vragen</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>antworten</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich antworte — ik antwoord</div><div class=\"kurss-example\">du antwortest — jij antwoordt</div><div class=\"kurss-example\">er antwortet — hij antwoordt</div><div class=\"kurss-example\">sie antwortet — zij antwoordt</div><div class=\"kurss-example\">wir antworten — wij antwoorden</div><div class=\"kurss-example\">ihr antwortet — jullie antwoorden</div><div class=\"kurss-example\">sie antworten — zij antwoorden</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>rechnen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich rechne — ik reken</div><div class=\"kurss-example\">du rechnest — jij rekent</div><div class=\"kurss-example\">er rechnet — hij rekent</div><div class=\"kurss-example\">sie rechnet — zij rekent</div><div class=\"kurss-example\">wir rechnen — wij rekenen</div><div class=\"kurss-example\">ihr rechnet — jullie rekenen</div><div class=\"kurss-example\">sie rechnen — zij rekenen</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>zeichnen</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich zeichne — ik teken</div><div class=\"kurss-example\">du zeichnest — jij tekent</div><div class=\"kurss-example\">er zeichnet — hij tekent</div><div class=\"kurss-example\">sie zeichnet — zij tekent</div><div class=\"kurss-example\">wir zeichnen — wij tekenen</div><div class=\"kurss-example\">ihr zeichnet — jullie tekenen</div><div class=\"kurss-example\">sie zeichnen — zij tekenen</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>tun</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich tue — ik doe</div><div class=\"kurss-example\">du tust — jij doet</div><div class=\"kurss-example\">er tut — hij doet</div><div class=\"kurss-example\">sie tut — zij doet</div><div class=\"kurss-example\">wir tun — wij doen</div><div class=\"kurss-example\">ihr tut — jullie doen</div><div class=\"kurss-example\">sie tun — zij doen</div></div>\n            </section>",
  "kurssSentenceStructureLesson": "\n            <h3>Zinsbouw</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n              <span class=\"artikuli-info-icon\">i</span>\n              <div>In een vraagzin staat het werkwoord in het Duits meestal op de eerste plaats.</div>\n            </div>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Voorbeelden</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Du kommst. — Jij komt.</div><div class=\"kurss-example\">Kommst du? — Kom jij?</div><div class=\"kurss-example\">Er singt. — Hij zingt.</div><div class=\"kurss-example\">Singt er? — Zingt hij?</div><div class=\"kurss-example\">Stehst du? — Sta jij?</div><div class=\"kurss-example\">Ja, ich stehe. — Ja, ik sta.</div><div class=\"kurss-example\">Geht ihr? — Gaan jullie?</div><div class=\"kurss-example\">Ja, wir gehen. — Ja, wij gaan.</div></div>\n            </section>\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Vragen met “was”</h4>\n              <p class=\"artikuli-explain\">Als een vraag begint met een vraagwoord, staat het werkwoord in het Duits meestal direct na het vraagwoord.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Was tust du? — Wat doe jij?</div><div class=\"kurss-example\">Was tut er? — Wat doet hij?</div><div class=\"kurss-example\">Was tut sie? — Wat doet zij?</div><div class=\"kurss-example\">Was tun sie? — Wat doen zij?</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Ontkenning met “nicht”</h4>\n              <p class=\"artikuli-explain\">Als de ontkenning “nicht” bij het werkwoord hoort, staat die in het Duits meestal na het werkwoord.</p>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Ich spiele nicht. — Ik speel niet.</div><div class=\"kurss-example\">Paul fragt nicht. — Paul vraagt niet.</div><div class=\"kurss-example\">Er kommt nicht. — Hij komt niet.</div><div class=\"kurss-example\">Sie singen nicht. — Zij zingen niet.</div></div>\n            </section>\n\n            <section class=\"artikuli-block\">\n              <h4 class=\"artikuli-header\"><span>•</span>Zinnen uit les 2</h4>\n              <div class=\"artikuli-grid\"><div class=\"kurss-example\">Spielst du? — Speel jij?</div><div class=\"kurss-example\">Nein, ich spiele nicht, ich arbeite. — Nee, ik speel niet, ik werk.</div><div class=\"kurss-example\">Paul fragt nicht, er arbeitet. — Paul vraagt niet, hij werkt.</div><div class=\"kurss-example\">Arbeitest du? — Werk jij?</div><div class=\"kurss-example\">Nein, ich arbeite nicht, ich singe. — Nee, ik werk niet, ik zing.</div><div class=\"kurss-example\">Was tut Paul? — Wat doet Paul?</div><div class=\"kurss-example\">Er spielt. — Hij speelt.</div><div class=\"kurss-example\">Was tut Marie? — Wat doet Marie?</div><div class=\"kurss-example\">Sie singt. — Zij zingt.</div><div class=\"kurss-example\">Paul spielt, aber Marie singt. — Paul speelt, maar Marie zingt.</div><div class=\"kurss-example\">Singt ihr? — Zingen jullie?</div><div class=\"kurss-example\">Nein, wir singen nicht, wir arbeiten. — Nee, wij zingen niet, wij werken.</div><div class=\"kurss-example\">Was tun Paul und Marie? — Wat doen Paul en Marie?</div><div class=\"kurss-example\">Sie fragen. — Zij vragen.</div><div class=\"kurss-example\">Sie antworten nicht. — Zij antwoorden niet.</div><div class=\"kurss-example\">Wer arbeitet? — Wie werkt?</div><div class=\"kurss-example\">Wir arbeiten. — Wij werken.</div><div class=\"kurss-example\">Wir rechnen und zeichnen. — Wij rekenen en tekenen.</div><div class=\"kurss-example\">Sie kommen, sie fragen, sie antworten, sie arbeiten, sie spielen, sie singen, sie gehen. — Zij komen, vragen, antwoorden, werken, spelen, zingen en gaan.</div></div>\n            </section>",
  "kurssLesson2": "            <h3>Les 2</h3>\n            <p class=\"kurss-lesson-intro\">Tweede les: dialogen, woorden, uitspraak, grammatica en vertalen.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialogen / zinnen</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\">\n                  <div class=\"kurss-example\">Spielst du?<br>Nein, ich spiele nicht, ich arbeite.</div>\n                  <div class=\"kurss-example\">Paul fragt nicht, er arbeitet.</div>\n                  <div class=\"kurss-example\">Arbeitest du?<br>Nein, ich arbeite nicht, ich singe.</div>\n                  <div class=\"kurss-example\">Was tut Paul?<br>Er spielt.</div>\n                  <div class=\"kurss-example\">Was tut Marie?<br>Sie singt.</div>\n                  <div class=\"kurss-example\">Paul spielt, aber Marie singt.</div>\n                  <div class=\"kurss-example\">Singt ihr?<br>Nein, wir singen nicht, wir arbeiten.</div>\n                  <div class=\"kurss-example\">Was tun Paul und Marie?<br>Sie fragen.<br>Sie antworten nicht.</div>\n                  <div class=\"kurss-example\">Wer arbeitet?<br>Wir arbeiten.<br>Wir rechnen und zeichnen.</div>\n                  <div class=\"kurss-example\">Sie kommen, sie fragen, sie antworten, sie arbeiten, sie spielen, sie singen, sie gehen.</div>\n                </div>\n              </div>\n            </details>\n            <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Woorden</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\">\n                  <div class=\"kurss-example\">spielen — spelen</div>\n                  <div class=\"kurss-example\">nein — nee</div>\n                  <div class=\"kurss-example\">nicht — niet</div>\n                  <div class=\"kurss-example\">arbeiten — werken</div>\n                  <div class=\"kurss-example\">fragen — vragen</div>\n                  <div class=\"kurss-example\">was tut er? — wat doet hij?</div>\n                  <div class=\"kurss-example\">was tun sie? — wat doen zij?</div>\n                  <div class=\"kurss-example\">aber — maar</div>\n                  <div class=\"kurss-example\">antworten — antwoorden</div>\n                  <div class=\"kurss-example\">rechnen — rekenen</div>\n                  <div class=\"kurss-example\">zeichnen — tekenen</div>\n                  <div class=\"kurss-example\">Marie — Maria</div>\n                </div>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Uitspraak</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">In de woorden ich, nicht, rechnen, zeichnen wordt de klank ch zacht uitgesproken: niet achter in de keel zoals de Nederlandse ch, maar voor in de mond, ongeveer als een stemloze j.</div><div class=\"kurss-example\">In de woorden arbeiten, zeichnen wordt de tweeklank ei ongeveer uitgesproken als ai, zoals in het Nederlandse haai.</div><div class=\"kurss-example\">De medeklinkercombinatie sp wordt uitgesproken als sjp: spielen (sjpielen).</div><div class=\"kurss-example\">In het werkwoord tun wordt de u in alle personen lang uitgesproken.</div></div>\n              </div>\n            </details>\n<details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammatica</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content lesson1-grammar-content\">\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>1</span>Uitgangen met e</h4>\n                  <div class=\"lesson1-grammar-note\">Als de stam van het werkwoord eindigt op t, d, chn, dan staat bij de vervoeging een e vóór de uitgangen -st en -t.</div>\n                  <h5 class=\"lesson2-subtitle\">arbeiten</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich arbeite</div><div class=\"kurss-example\">du arbeitest</div><div class=\"kurss-example\">er arbeitet</div><div class=\"kurss-example\">sie arbeitet</div><div class=\"kurss-example\">wir arbeiten</div><div class=\"kurss-example\">ihr arbeitet</div><div class=\"kurss-example\">sie arbeiten</div></div>\n                  <h5 class=\"lesson2-subtitle\">rechnen</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich rechne</div><div class=\"kurss-example\">du rechnest</div><div class=\"kurss-example\">er rechnet</div><div class=\"kurss-example\">sie rechnet</div><div class=\"kurss-example\">wir rechnen</div><div class=\"kurss-example\">ihr rechnet</div><div class=\"kurss-example\">sie rechnen</div></div>\n                  <h5 class=\"lesson2-subtitle\">tun</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich tue</div><div class=\"kurss-example\">du tust</div><div class=\"kurss-example\">er tut</div><div class=\"kurss-example\">sie tut</div><div class=\"kurss-example\">wir tun</div><div class=\"kurss-example\">ihr tut</div><div class=\"kurss-example\">sie tun</div></div>\n                </section>\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>2</span>Vraagwoord</h4>\n                  <div class=\"lesson1-grammar-note\">In vraagzinnen die met een vraagwoord beginnen, bijvoorbeeld: wat? wie? welke? waarom? waarvoor? enz., staat het werkwoord direct na het vraagwoord.</div>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Was tust du? — Wat doe jij?</div><div class=\"kurss-example\">Was tut er? — Wat doet hij?</div><div class=\"kurss-example\">Was tut sie? — Wat doet zij?</div><div class=\"kurss-example\">Was tun sie? — Wat doen zij?</div></div>\n                </section>\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>3</span>Ontkenning met nicht</h4>\n                  <div class=\"lesson1-grammar-note\">Als de ontkenning nicht bij het werkwoord hoort, staat het ontkennende woord na het werkwoord.</div>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Er kommt nicht. — Hij komt niet.</div><div class=\"kurss-example\">Sie singen nicht. — Zij zingen niet.</div></div>\n                </section>\n              </div>\n            </details>\n                                    <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Vertaal</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-training-wrap\">\n                  <button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson2-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Les 2 vertaalkaart\">\n                    <span class=\"lesson1-training-progress\">Les 2 · Vertaal: 1 / 15</span>\n                    <span class=\"lesson1-training-text\">Wie vraagt?</span>\n                  </button>\n                  <p class=\"lesson1-training-hint\">Klik op de kaart om de Duitse vertaling te zien. Na het antwoord toont de volgende klik de volgende kaart.</p>\n                </div>\n              </div>\n            </details>",
  "kurssLesson6": "\n    <h3>Les 6</h3>\n    <p class=\"kurss-lesson-intro\">Telwoorden, meervoud, umlauten en meervoudsvormen van zelfstandige naamwoorden.</p>\n\n    <details class=\"lesson1-accordion\" open>\n      <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialogen / zinnen</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hier liegt ein Bleistift.</div><div class=\"kurss-example\">Dort liegen einige Messer.</div><div class=\"kurss-example\">Edgar nimmt ein Messer, zwei Messer, drei Messer.</div><div class=\"kurss-example\">Er legt die Messer wieder hin.</div><div class=\"kurss-example\">Alle Messer sind scharf.</div><div class=\"kurss-example\">Dann nimmt er wieder ein Messer.</div><div class=\"kurss-example\">Er macht das Messer auf.</div><div class=\"kurss-example\">Er nimmt den Bleistift.</div><div class=\"kurss-example\">Er spitzt den Bleistift an.</div><div class=\"kurss-example\">Er legt das Messer hin.</div><div class=\"kurss-example\">Er setzt sich und zeichnet.</div><div class=\"kurss-example\">Was zeichnet er? Er zeichnet einen Schlüssel.</div><div class=\"kurss-example\">Gertrud zeichnet ein Fenster und eine Tafel.</div><div class=\"kurss-example\">Anna zeichnet einen Garten.</div><div class=\"kurss-example\">Hier liegen vier Löffel.</div><div class=\"kurss-example\">Dort liegen fünf Nadeln.</div><div class=\"kurss-example\">Gertrud kommt und zählt die Löffel: das ist ein Löffel; das sind zwei, drei, vier Löffel.</div><div class=\"kurss-example\">Anna zählt die Nadeln: das ist eine Nadel; das sind zwei, drei, vier, fünf Nadeln.</div><div class=\"kurss-example\">Wieviel Nadeln sind hier?</div><div class=\"kurss-example\">Hier ist eine Nadel.</div><div class=\"kurss-example\">Dort sind zwei, drei, vier Nadeln.</div><div class=\"kurss-example\">Fünf Schlüssel sind hier.</div><div class=\"kurss-example\">Sechs Löffel sind dort.</div><div class=\"kurss-example\">Was ist das?</div><div class=\"kurss-example\">Das ist ein Hammer. Das sind fünf Hämmer.</div><div class=\"kurss-example\">Das ist ein Deckel. Das sind sechs Deckel.</div><div class=\"kurss-example\">Das ist ein Eimer. Das sind sieben Eimer.</div><div class=\"kurss-example\">Das ist ein Teller. Das sind acht Teller.</div><div class=\"kurss-example\">Das ist ein Wagen. Das sind neun Wagen.</div><div class=\"kurss-example\">Das ist ein Schlitten. Das sind zehn Schlitten.</div><div class=\"kurss-example\">Wie sind die Dinge?</div><div class=\"kurss-example\">Der Hammer ist klein. Die Hämmer sind klein.</div><div class=\"kurss-example\">Der Deckel ist groß. Die Deckel sind groß.</div><div class=\"kurss-example\">Der Eimer ist voll. Die Eimer sind voll.</div><div class=\"kurss-example\">Der Teller ist leer. Die Teller sind leer.</div><div class=\"kurss-example\">Der Wagen ist schwer. Die Wagen sind schwer.</div><div class=\"kurss-example\">Der Schlitten ist leicht. Die Schlitten sind leicht.</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Woorden</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">liegt — ligt, is, bevindt zich</div><div class=\"kurss-example\">der Bleistift (blaisjtift) — het potlood</div><div class=\"kurss-example\">einige (ainige) — enkele, sommige</div><div class=\"kurss-example\">hinlegen — neerleggen</div><div class=\"kurss-example\">legt hin — legt neer</div><div class=\"kurss-example\">wieder (vieder) — weer, opnieuw</div><div class=\"kurss-example\">aufmachen — opendoen</div><div class=\"kurss-example\">er macht auf — hij doet open</div><div class=\"kurss-example\">anspitzen (ansjpitsen) — slijpen, punten</div><div class=\"kurss-example\">er spitzt an — hij slijpt</div><div class=\"kurss-example\">sich setzen — gaan zitten</div><div class=\"kurss-example\">setzt sich — gaat zitten</div><div class=\"kurss-example\">der Schlüssel (sjlussel) — de sleutel</div><div class=\"kurss-example\">das Fenster (fenster) — het raam</div><div class=\"kurss-example\">die Tafel (die taafel) — het schoolbord</div><div class=\"kurss-example\">der Garten — de tuin</div><div class=\"kurss-example\">der Löffel — de lepel</div><div class=\"kurss-example\">zählen (tseelen) — tellen</div><div class=\"kurss-example\">die Nadel — de naald</div><div class=\"kurss-example\">was ist das — wat is dat?</div><div class=\"kurss-example\">der Hammer — de hamer</div><div class=\"kurss-example\">die Hämmer — de hamers</div><div class=\"kurss-example\">der Deckel (deer dekkel) — het deksel</div><div class=\"kurss-example\">der Teller — het bord</div><div class=\"kurss-example\">der Wagen — de wagen, de kar</div><div class=\"kurss-example\">der Schlitten — de slee</div><div class=\"kurss-example\">das Ding — het ding</div><div class=\"kurss-example\">die Dinge — de dingen</div><div class=\"kurss-example\">wie sind die Dinge? — hoe zijn de dingen?</div><div class=\"kurss-example\">voll (fol) — vol</div><div class=\"kurss-example\">leer (leer) — leeg</div><div class=\"kurss-example\">schwer (sjveer) — zwaar, moeilijk</div><div class=\"kurss-example\">leicht — licht</div><div class=\"kurss-example\">der Eimer — de emmer</div><div class=\"kurss-example\">wieviel (viefiel) — hoeveel</div><div class=\"kurss-example\">wieviel Nadeln — hoeveel naalden</div><div class=\"kurss-example\">hier (hier) — hier</div><div class=\"kurss-example\">dort — daar</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Uitspraak</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ä is de umlaut van de klinker a en wordt uitgesproken als een korte of lange open e, zoals in bed of crème.</div><div class=\"kurss-example\">Voorbeelden: das Mädchen (meetchen), die Bänke (die benke), der Vater (deer faater), die Väter (die feeter).</div><div class=\"kurss-example\">ü is de umlaut van de klinker u. Hij klinkt als de Nederlandse uu in muur: rond de lippen sterk en zeg dan i.</div><div class=\"kurss-example\">Voorbeelden: fünf, der Schlüssel (sjlussel).</div><div class=\"kurss-example\">ö spreek je uit met geronde lippen terwijl je e probeert te zeggen, ongeveer als de Nederlandse eu: der Löffel.</div><div class=\"kurss-example\">Een verdubbelde klinker duidt een lange klinker aan: leer (leer).</div><div class=\"kurss-example\">De tweeklank eu wordt uitgesproken als oi: neun (noin).</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammatica</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content lesson1-grammar-content\">\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Grammatica en toelichting</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Het beklemtoonde voorvoegsel van een samengesteld werkwoord wordt in de tegenwoordige tijd van het werkwoord gescheiden en staat aan het eind van de zin.</div><div class=\"kurss-example\">Voorbeelden: hinlegen — er legt hin; aufmachen — er macht auf; anspitzen — er spitzt an.</div><div class=\"kurss-example\">Het telwoord één heeft, als het bij een zelfstandig naamwoord staat, drie geslachten: mannelijk ein, vrouwelijk eine, onzijdig ein.</div><div class=\"kurss-example\">Voorbeelden: ein Schüler — één leerling; eine Schülerin — één leerlinge; ein Kind — één kind.</div><div class=\"kurss-example\">Telwoorden: eins, zwei, drei, vier (fier), fünf, sechs (zeks), sieben (zieben), acht, neun (noin), zehn (tseen).</div><div class=\"kurss-example\">Het koppelwerkwoord heeft in het Duits een enkelvouds- en een meervoudsvorm: der Schüler ist klein; die Schüler sind klein.</div><div class=\"kurss-example\">Net als het Nederlandse dat in dat is / dat zijn gebruikt het Duits hier één vorm voor alle geslachten en getallen: das.</div><div class=\"kurss-example\">Voorbeelden: dat is een hamer — das ist ein Hammer; dat is een naald — das ist eine Nadel; dat zijn hamers — das sind Hämmer; dat zijn naalden — das sind Nadeln.</div><div class=\"kurss-example\">Der Wagen — wagen en der Schlitten — slee worden in het Duits, net als in het Nederlands, in het enkelvoud en in het meervoud gebruikt.</div><div class=\"kurss-example\">Mannelijke en onzijdige zelfstandige naamwoorden op -er, -el, -en krijgen in het meervoud vaak geen uitgang.</div><div class=\"kurss-example\">Voorbeelden: der Hammer — die Hämmer; der Garten — die Gärten; das Fenster — die Fenster; das Messer — die Messer.</div><div class=\"kurss-example\">Vrouwelijke zelfstandige naamwoorden op -el, -er krijgen in het meervoud -n.</div><div class=\"kurss-example\">Voorbeelden: die Nadel — die Nadeln; die Feder — die Federn.</div><div class=\"kurss-example\">Uitzonderingen: die Mutter (moeder) — die Mütter (moeders); die Tochter (dochter) — die Töchter (dochters).</div><div class=\"kurss-example\">Het onbepaald lidwoord heeft geen meervoud: das ist ein Wagen — das sind Wagen; das ist eine Nadel — das sind Nadeln.</div><div class=\"kurss-example\">In een mededelende zin staat de persoonsvorm op de tweede plaats: er legt den Schlüssel hin; dann legt er den Schlüssel hin.</div></div></section>\n      </div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Vertaal</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson6-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Les 6 vertaalkaart\"><span class=\"lesson1-training-progress\">Les 6 · Vertaal: 1 / 21</span><span class=\"lesson1-training-text\">Paul neemt een potlood en tekent.</span></button><p class=\"lesson1-training-hint\">Klik op de kaart om de Duitse vertaling te zien. Na het antwoord toont de volgende klik de volgende kaart.</p></div></div>\n    </details>\n  ",
  "kurssLesson5": "\n    <h3>Les 5</h3>\n    <p class=\"kurss-lesson-intro\">Wen?, accusatief, sitzen, fragen en de uitgang -in.</p>\n\n    <details class=\"lesson1-accordion\" open>\n      <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialogen / zinnen</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">Wer sitzt und fragt? Der Lehrer sitzt und fragt.</div>\n        <div class=\"kurss-example\">Wer steht und antwortet? Der Schüler steht und antwortet.</div>\n        <div class=\"kurss-example\">Wie antwortet der Schüler? Der Schüler antwortet gut.</div>\n        <div class=\"kurss-example\">Wen lobt der Lehrer? Der Lehrer lobt den Schüler.</div>\n        <div class=\"kurss-example\">Wie ist der Schüler? Der Schüler ist klein.</div>\n        <div class=\"kurss-example\">Ist der Schüler klein oder groß? Er ist klein.</div>\n        <div class=\"kurss-example\">Wen fragt die Lehrerin? Die Lehrerin fragt die Schülerin.</div>\n        <div class=\"kurss-example\">Wie antwortet die Schülerin? Die Schülerin antwortet schlecht.</div>\n        <div class=\"kurss-example\">Was tut die Lehrerin? Sie tadelt die Schülerin.</div>\n        <div class=\"kurss-example\">Die Schülerin ist nicht klein, sie ist groß.</div>\n        <div class=\"kurss-example\">Ein Kind spielt. Das Kind ist artig.</div>\n        <div class=\"kurss-example\">Die Mutter liebt das Kind. Der Vater lobt das Kind.</div>\n      </div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Woorden</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">sitzen (zitsen) — zitten</div>\n        <div class=\"kurss-example\">fragen (fraagen) — vragen</div>\n        <div class=\"kurss-example\">der Lehrer (deer leerer) — de leraar</div>\n        <div class=\"kurss-example\">gut (goet) — goed</div>\n        <div class=\"kurss-example\">wen (veen) — wie</div>\n        <div class=\"kurss-example\">loben — prijzen</div>\n        <div class=\"kurss-example\">der Schüler (sjuuler) — de leerling</div>\n        <div class=\"kurss-example\">klein — klein</div>\n        <div class=\"kurss-example\">groß (groos) — groot</div>\n        <div class=\"kurss-example\">die Lehrerin — de lerares</div>\n        <div class=\"kurss-example\">die Schülerin — de leerlinge</div>\n        <div class=\"kurss-example\">schlecht (sjlecht) — slecht</div>\n        <div class=\"kurss-example\">tadeln — berispen</div>\n        <div class=\"kurss-example\">oder (ooder) — of</div>\n        <div class=\"kurss-example\">das Kind (kint) — het kind</div>\n        <div class=\"kurss-example\">artig (aartich) — braaf</div>\n        <div class=\"kurss-example\">die Mutter — de moeder</div>\n        <div class=\"kurss-example\">lieben (lieben) — liefhebben, houden van</div>\n        <div class=\"kurss-example\">der Vater (faater) — de vader</div>\n      </div></div>\n    </details>\n\n        <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Uitspraak</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">tz is een verdubbelde z en wordt uitgesproken als ts: sitzen (zitsen).</div>\n        <div class=\"kurss-example\">v wordt in Duitse woorden uitgesproken als f: der Vater (faater).</div>\n        <div class=\"kurss-example\">ß heet eszett en wordt uitgesproken als een Nederlandse s: groß (groos), weiß (vais).</div>\n      </div></div>\n    </details>\n\n<details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammatica</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content lesson1-grammar-content\">\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Nominatief en accusatief</h4><div class=\"lesson1-grammar-note\">In het Nederlands beantwoorden zowel het onderwerp als het lijdend voorwerp de vraag wie? of wat?; in het Duits staat het onderwerp in de nominatief en het lijdend voorwerp in de accusatief.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">In het Duits is het vraagwoord in de nominatief wer? voor personen en was? voor dingen.</div><div class=\"kurss-example\">In de accusatief is het vraagwoord wen? voor personen en was? voor dingen.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Verandering van het lidwoord in de accusatief</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nominativ: der Vater, die Mutter, das Kind.</div><div class=\"kurss-example\">Akkusativ: den Vater, die Mutter, das Kind.</div><div class=\"kurss-example\">Nominativ: der Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Akkusativ: den Federhalter, die Feder, das Messer.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">sitzen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich sitze</div><div class=\"kurss-example\">du sitzt</div><div class=\"kurss-example\">er/sie/es sitzt</div><div class=\"kurss-example\">wir sitzen</div><div class=\"kurss-example\">ihr sitzt</div><div class=\"kurss-example\">sie sitzen</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">fragen + accusatief</h4><div class=\"lesson1-grammar-note\">Het werkwoord fragen vraagt in het Duits de accusatief.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Wen fragt der Lehrer?</div><div class=\"kurss-example\">Der Lehrer fragt den Schüler.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">De uitgang -in</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Veel vrouwelijke woorden worden afgeleid met de uitgang -in.</div><div class=\"kurss-example\">die Lehrerin</div><div class=\"kurss-example\">die Schülerin</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Plaats van het werkwoord</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">In een mededelende zin staat het werkwoord op de tweede plaats.</div><div class=\"kurss-example\">Dann geht das Mädchen hinaus und arbeitet.</div><div class=\"kurss-example\">Das Mädchen geht dann hinaus und arbeitet.</div></div></section>\n      </div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Vertaal</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson5-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Les 5 vertaalkaart\"><span class=\"lesson1-training-progress\">Les 5 · Vertaal: 1 / 16</span><span class=\"lesson1-training-text\">Van wie houdt de vader?</span></button><p class=\"lesson1-training-hint\">Klik op de kaart om de Duitse vertaling te zien. Na het antwoord toont de volgende klik de volgende kaart.</p></div></div>\n    </details>\n  ",
  "kurssLesson4": "            <h3>Les 4</h3>\n            <p class=\"kurss-lesson-intro\">Accusatief, nehmen, hinlegen, hinausgehen en bijvoeglijke naamwoorden.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialogen / zinnen</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Paul kommt und nimmt einen Federhalter.</div><div class=\"kurss-example\">Er zeigt den Federhalter.</div><div class=\"kurss-example\">Er fragt: „Wie ist der Federhalter?“</div><div class=\"kurss-example\">Olga antwortet: „Der Federhalter ist schwarz.“</div><div class=\"kurss-example\">Ist der Federhalter weiß? Nein, der Federhalter ist nicht weiß, er ist schwarz.</div><div class=\"kurss-example\">Marie kommt und nimmt eine Feder.</div><div class=\"kurss-example\">Sie fragt: „Wie ist die Feder?“</div><div class=\"kurss-example\">Olga antwortet: „Die Feder ist spitz.“</div><div class=\"kurss-example\">Ist die Feder stumpf? Nein, die Feder ist nicht stumpf, sie ist spitz.</div><div class=\"kurss-example\">Was legt das Mädchen hin? Es legt die Feder hin.</div><div class=\"kurss-example\">Was nimmst du? Ich nehme ein Messer.</div><div class=\"kurss-example\">Wie ist das Messer? Das Messer ist scharf.</div><div class=\"kurss-example\">Ist das Messer stumpf? Nein, es ist nicht stumpf, es ist scharf.</div><div class=\"kurss-example\">Was legst du hin? Ich lege das Messer, die Feder und den Federhalter hin.</div><div class=\"kurss-example\">Dann gehe ich hinaus und arbeite.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Woorden</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">nehmen (neemen) — nemen</div><div class=\"kurss-example\">er nimmt (nimt) — hij neemt</div><div class=\"kurss-example\">der Federhalter (deer feederhalter) — de penhouder</div><div class=\"kurss-example\">einen Federhalter — een penhouder</div><div class=\"kurss-example\">zeigen — tonen, laten zien</div><div class=\"kurss-example\">schwarz (sjvarts) — zwart</div><div class=\"kurss-example\">weiß (vais) — wit</div><div class=\"kurss-example\">die Feder (die feeder) — de pen</div><div class=\"kurss-example\">eine Feder — een pen</div><div class=\"kurss-example\">spitz (sjpits) — puntig, spits</div><div class=\"kurss-example\">hinlegen — neerleggen</div><div class=\"kurss-example\">legt hin — legt neer</div><div class=\"kurss-example\">das Mädchen (meetchen) — het meisje</div><div class=\"kurss-example\">das Messer — het mes</div><div class=\"kurss-example\">ein Messer — een mes</div><div class=\"kurss-example\">scharf — scherp</div><div class=\"kurss-example\">stumpf (sjtoempf) — bot, stomp</div><div class=\"kurss-example\">dann — dan</div><div class=\"kurss-example\">hinaus — naar buiten</div><div class=\"kurss-example\">hinausgehen — naar buiten gaan</div></div></div></details>\n                        <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Uitspraak</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">De uitgangen -en, -er, -el zijn onbeklemtoond, daarom is de e in deze uitgangen nauwelijks hoorbaar: kommen, nehmen, der Federhalter.</div><div class=\"kurss-example\">h kan in het Duits zowel een klank zijn als een lengteteken voor de voorafgaande klinker.</div><div class=\"kurss-example\">Als h een lengteteken is, wordt de h niet als klank uitgesproken: nehmen (neemen).</div><div class=\"kurss-example\">Als op een klinker maar één medeklinker volgt, wordt de klinker lang uitgesproken: die (die) Feder (feeder), den (deen).</div></div></div></details>\n<details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammatica</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Accusatief</h4><div class=\"lesson1-grammar-note\">In het vrouwelijk en het onzijdig is de accusatief gelijk aan de nominatief. Alleen het mannelijk verandert.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nominativ: der Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Akkusativ: den Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Nominativ: ein Federhalter, eine Feder, ein Messer.</div><div class=\"kurss-example\">Akkusativ: einen Federhalter, eine Feder, ein Messer.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>nehmen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich nehme</div><div class=\"kurss-example\">du nimmst</div><div class=\"kurss-example\">er/sie nimmt</div><div class=\"kurss-example\">wir nehmen</div><div class=\"kurss-example\">ihr nehmt</div><div class=\"kurss-example\">sie nehmen</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Voornaamwoorden</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">er — mannelijk</div><div class=\"kurss-example\">sie — vrouwelijk</div><div class=\"kurss-example\">es — onzijdig</div><div class=\"kurss-example\">meervoud — sie</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>Scheidbare werkwoorden</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">hinlegen → ich lege das Messer hin</div><div class=\"kurss-example\">hinausgehen → Marie geht hinaus</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>5</span>Bijvoeglijke naamwoorden</h4><div class=\"lesson1-grammar-note\">Als het bijvoeglijk naamwoord in de zin deel van het gezegde is, verandert het niet naar geslacht of getal.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">der Federhalter ist klein</div><div class=\"kurss-example\">die Feder ist klein</div><div class=\"kurss-example\">das Messer ist klein</div><div class=\"kurss-example\">die Messer sind klein</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>6</span>Ontkenning met nicht</h4><div class=\"lesson1-grammar-note\">Als nicht een bijvoeglijk naamwoord ontkent, staat het vóór het ontkende woord.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">der Federhalter ist nicht weiß</div><div class=\"kurss-example\">das Messer ist nicht scharf</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>7</span>-chen / -lein</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Zelfstandige naamwoorden op -chen en -lein zijn onzijdig: das Mädchen.</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Vertaal</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson4-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Les 4 vertaalkaart\"><span class=\"lesson1-training-progress\">Les 4 · Vertaal: 1 / 16</span><span class=\"lesson1-training-text\">Het meisje neemt een penhouder.</span></button><p class=\"lesson1-training-hint\">Klik op de kaart om de Duitse vertaling te zien. Na het antwoord toont de volgende klik de volgende kaart.</p></div></div></details>",
  "kurssLesson3": "            <h3>Les 3</h3>\n            <p class=\"kurss-lesson-intro\">Derde les: dialogen, woorden, uitspraak, grammatica en vertalen.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialogen / zinnen</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Wer rechnet und zeichnet?<br>Wir rechnen und zeichnen.</div><div class=\"kurss-example\">Wer kommt?<br>Paul und Anna kommen.</div><div class=\"kurss-example\">Was steht hier?<br>Hier steht ein Tisch.</div><div class=\"kurss-example\">Was steht dort?<br>Dort steht eine Bank.</div><div class=\"kurss-example\">Was liegt hier?<br>Hier liegt ein Buch.</div><div class=\"kurss-example\">Was liegt dort?<br>Dort liegt ein Heft.</div><div class=\"kurss-example\">Was hängt hier?<br>Hier hängt ein Bild.</div><div class=\"kurss-example\">Was hängt dort?<br>Dort hängt eine Tafel.</div><div class=\"kurss-example\">Wie ist das Buch?<br>Das Buch ist dick.</div><div class=\"kurss-example\">Wie ist das Heft?<br>Das Heft ist dünn.</div><div class=\"kurss-example\">Wie ist die Bank?<br>Die Bank ist niedrig.</div><div class=\"kurss-example\">Wie ist der Tisch?<br>Der Tisch ist hoch.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Woorden</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">wer — wie</div><div class=\"kurss-example\">was — wat</div><div class=\"kurss-example\">hier — hier</div><div class=\"kurss-example\">dort — daar</div><div class=\"kurss-example\">der Tisch — de tafel</div><div class=\"kurss-example\">ein Tisch — een tafel</div><div class=\"kurss-example\">die Bank — de bank</div><div class=\"kurss-example\">eine Bank — een bank</div><div class=\"kurss-example\">liegen — liggen</div><div class=\"kurss-example\">liegt hier ein Buch? — ligt hier een boek?</div><div class=\"kurss-example\">das Buch — het boek</div><div class=\"kurss-example\">ein Buch — een boek</div><div class=\"kurss-example\">hängen — hangen</div><div class=\"kurss-example\">das Bild — het schilderij</div><div class=\"kurss-example\">ein Bild — een schilderij</div><div class=\"kurss-example\">die Tafel — het schoolbord</div><div class=\"kurss-example\">eine Tafel — een schoolbord</div><div class=\"kurss-example\">wie — hoe</div><div class=\"kurss-example\">ist — is</div><div class=\"kurss-example\">dick — dik</div><div class=\"kurss-example\">das Heft — het schrift</div><div class=\"kurss-example\">ein Heft — een schrift</div><div class=\"kurss-example\">dünn — dun</div><div class=\"kurss-example\">niedrig — laag</div><div class=\"kurss-example\">hoch — hoog</div></div></div></details>\n                        <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Uitspraak</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">De lange i-klank wordt in het Duits geschreven als ie: liegen (liegen), hier (hier), wie (vie).</div><div class=\"kurss-example\">ck is een dubbele k: dick (dik).</div><div class=\"kurss-example\">In bijvoeglijke naamwoorden en bijwoorden klinkt de uitgang -ig als een zachte -ich: niedrig (niedrich).</div><div class=\"kurss-example\">Als na de uitgang -ig een e volgt: -ige, dan wordt de g uitgesproken als een harde g, zoals in het Engelse go: niedrige (niedrige) Bänke.</div></div></div></details>\n<details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammatica</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Onderwerp</h4><div class=\"lesson1-grammar-note\">Het onderwerp antwoordt in het Duits op de vraag wer? / was? en staat in de nominatief.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Met wer? vraag je naar personen.</div><div class=\"kurss-example\">Met was? vraag je naar dingen.</div><div class=\"kurss-example\">Wer singt? — Sie singt.</div><div class=\"kurss-example\">Was liegt hier? — Hier liegt ein Buch.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>Lidwoorden</h4><div class=\"lesson1-grammar-note\">In het Duits heeft een zelfstandig naamwoord 3 geslachten: mannelijk, vrouwelijk en onzijdig. Voor een zelfstandig naamwoord staat meestal een woordje dat lidwoord heet. Dit woordje laat zich niet altijd één op één vertalen.</div><h5 class=\"lesson2-subtitle\">Bepaald lidwoord</h5><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">mannelijk — der</div><div class=\"kurss-example\">vrouwelijk — die</div><div class=\"kurss-example\">onzijdig — das</div><div class=\"kurss-example\">In het meervoud is het bepaald lidwoord voor alle drie geslachten die.</div><div class=\"kurss-example\">der Tisch — die Tische</div><div class=\"kurss-example\">die Bank — die Bänke</div><div class=\"kurss-example\">das Heft — die Hefte</div></div><h5 class=\"lesson2-subtitle\">Onbepaald lidwoord</h5><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">mannelijk — ein</div><div class=\"kurss-example\">vrouwelijk — eine</div><div class=\"kurss-example\">onzijdig — ein</div><div class=\"kurss-example\">Het onbepaald lidwoord heeft geen meervoud.</div><div class=\"kurss-example\">ein Tisch — Tische</div><div class=\"kurss-example\">ein Heft — Hefte</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Eigennamen</h4><div class=\"lesson1-grammar-note\">Voor eigennamen gebruik je geen lidwoord.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hans spielt, aber Marie singt.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>Plaats van het werkwoord</h4><div class=\"lesson1-grammar-note\">In een mededelende zin staat het werkwoord op de tweede plaats.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hier hängt eine Karte.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>5</span>stehen / liegen / hängen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">In het Duits zegt men van voorwerpen die rechtop staan, dat het voorwerp staat:<br>der Tisch steht<br>die Bank steht</div><div class=\"kurss-example\">Van voorwerpen die horizontaal liggen, zegt men dat ze liggen:<br>das Buch liegt<br>das Heft liegt</div><div class=\"kurss-example\">Voorwerpen kunnen ook hangen:<br>die Karte hängt<br>die Tafel hängt</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Vertaal</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson3-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Les 3 vertaalkaart\"><span class=\"lesson1-training-progress\">Les 3 · Vertaal: 1 / 22</span><span class=\"lesson1-training-text\">Reken jij?</span></button><p class=\"lesson1-training-hint\">Klik op de kaart om de Duitse vertaling te zien. Na het antwoord toont de volgende klik de volgende kaart.</p></div></div></details>",
  "kurssLesson7": "            <h3>Les 7</h3>\n            <p class=\"kurss-lesson-intro\">Zevende les: gebiedende wijs, beleefdheidsvorm en meervoud.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialogen / zinnen</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hans, singe ein Lied! Was tust du? Ich singe ein Lied.</div><div class=\"kurss-example\">Hans und Olga, singt ein Lied! Was tut ihr? Wir singen ein Lied.</div><div class=\"kurss-example\">Fräulein Müller, singen Sie, bitte, ein Lied! Was tun Sie? Ich singe ein Lied.</div><div class=\"kurss-example\">Hans, zähle die Teller! Was tut Hans? Er zählt die Teller.</div><div class=\"kurss-example\">Hans und Olga, zählt die Teller! Was tun Hans und Olga? Sie zählen die Teller.</div><div class=\"kurss-example\">Fräulein Müller, zählen Sie, bitte, die Teller!</div><div class=\"kurss-example\">Hans, öffne das Fenster! Was tut Hans? Er öffnet das Fenster.</div><div class=\"kurss-example\">Hans und Olga, öffnet die Fenster! Was tun Hans und Olga? Sie öffnen die Fenster.</div><div class=\"kurss-example\">Fräulein Müller, öffnen Sie, bitte, alle Fenster!</div><div class=\"kurss-example\">Fräulein Müller öffnet alle Fenster.</div><div class=\"kurss-example\">Das ist der Spiegel. Das sind die Spiegel.</div><div class=\"kurss-example\">Das ist der Lappen. Das sind die Lappen.</div><div class=\"kurss-example\">Das ist der Spaten. Das sind die Spaten.</div><div class=\"kurss-example\">Das ist der Besen. Das sind die Besen.</div><div class=\"kurss-example\">Das ist die Schaufel. Das sind die Schaufeln.</div><div class=\"kurss-example\">Das ist die Schüssel. Das sind die Schüsseln.</div><div class=\"kurss-example\">Das ist das Zimmer. Das sind die Zimmer.</div><div class=\"kurss-example\">Das ist das Ufer. Das sind die Ufer.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Woorden</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">singen — zingen</div><div class=\"kurss-example\">singe — zing</div><div class=\"kurss-example\">singt — zing (jullie)</div><div class=\"kurss-example\">singen Sie — zingt u</div><div class=\"kurss-example\">das Lied (das liet) — het lied</div><div class=\"kurss-example\">Sie — u</div><div class=\"kurss-example\">zählen — tellen</div><div class=\"kurss-example\">das Fräulein (froilain) — de juffrouw</div><div class=\"kurss-example\">der Müller — de molenaar</div><div class=\"kurss-example\">öffnen — openen</div><div class=\"kurss-example\">das Fenster (fenster) — het raam</div><div class=\"kurss-example\">alle — allen, iedereen</div><div class=\"kurss-example\">der Spiegel (sjpiegel) — de spiegel</div><div class=\"kurss-example\">der Lappen — de lap, de doek</div><div class=\"kurss-example\">der Spaten — de spade</div><div class=\"kurss-example\">der Besen — de bezem</div><div class=\"kurss-example\">die Schaufel — de schep</div><div class=\"kurss-example\">die Schüssel — de schaal, de kom</div><div class=\"kurss-example\">das Zimmer — de kamer</div><div class=\"kurss-example\">das Ufer (oefer) — de oever</div></div></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Uitspraak</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">sp aan het begin van een woord of lettergreep wordt uitgesproken als sjp: der Spiegel (deer sjpiegel).</div><div class=\"kurss-example\">sch wordt uitgesproken als de Nederlandse sj in sjaal: die Schaufel (die sjaufel), die Schüssel (die sjussel).</div><div class=\"kurss-example\">De tweeklank äu wordt uitgesproken als oi, zoals in hoi: das Fräulein (das froilain).</div></div></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammatica</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Gebiedende wijs</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">De gebiedende wijs in de 2e persoon enkelvoud komt overeen met de 2e persoon enkelvoud van het werkwoord zonder de persoonsuitgang -st, met de uitgang -e erbij.</div><div class=\"kurss-example\">Voorbeelden: antworte!, arbeite!, öffne!, zeichne!</div><div class=\"kurss-example\">Heel vaak wordt de uitgang -e weggelaten als de gebiedende wijs daardoor eenlettergrepig wordt: geh!, steh!, komm!, tu!, sing!, frag!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>Gebiedende wijs meervoud</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">De gebiedende wijs in de 2e persoon meervoud is gelijk aan de 2e persoon meervoud van de tegenwoordige tijd, maar wordt zonder voornaamwoord gebruikt.</div><div class=\"kurss-example\">Voorbeelden: antwortet!, arbeitet!, öffnet!, zeichnet!, geht!, steht!, tut!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Beleefdheidsvorm met Sie</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">De beleefdheidsvorm met “u” komt overeen met de 3e persoon meervoud. Het voornaamwoord Sie wordt met een hoofdletter geschreven en staat na het werkwoord.</div><div class=\"kurss-example\">Voorbeelden: antworten Sie!, arbeiten Sie!, öffnen Sie!, zeichnen Sie!, gehen Sie!, stehen Sie!, tun Sie!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>öffnen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Bij het werkwoord öffnen wordt voor een makkelijkere uitspraak in de 2e en 3e persoon enkelvoud en in de 2e persoon meervoud een e tussen stam en uitgang ingevoegd: du öffnest, er öffnet, ihr öffnet.</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Übung / Oefening</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson7-exercise-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Les 7 oefenkaart\"><span class=\"lesson1-training-progress\">Les 7 · Übung: 1 / 16</span><span class=\"lesson1-training-text\">fragen — vragen</span></button><p class=\"lesson1-training-hint\">Tik op de kaart om de gebiedende wijs te zien.</p></div></div></details>",
  "kurssLesson1": "            <h3>Les 1</h3>\n            <p class=\"kurss-lesson-intro\">Eerste les: werkwoorden in de tegenwoordige tijd, woordjes, uitspraak, grammatica en vertalen.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Werkwoorden in de tegenwoordige tijd</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-info\">Werkwoorden en hun vervoeging in de tegenwoordige tijd.</div>\n                <div class=\"lesson1-verb-cards\">\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>kommen — komen</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>komme</strong><span>ik kom</span><span>du</span><strong>kommst</strong><span>jij komt</span><span>er / sie</span><strong>kommt</strong><span>hij / zij komt</span><span>wir</span><strong>kommen</strong><span>wij komen</span><span>ihr</span><strong>kommt</strong><span>jullie komen</span><span>sie / Sie</span><strong>kommen</strong><span>zij komen / u komt</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>gehen — gaan</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>gehe</strong><span>ik ga</span><span>du</span><strong>gehst</strong><span>jij gaat</span><span>er / sie</span><strong>geht</strong><span>hij / zij gaat</span><span>wir</span><strong>gehen</strong><span>wij gaan</span><span>ihr</span><strong>geht</strong><span>jullie gaan</span><span>sie / Sie</span><strong>gehen</strong><span>zij gaan / u gaat</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>stehen — staan</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>stehe</strong><span>ik sta</span><span>du</span><strong>stehst</strong><span>jij staat</span><span>er / sie</span><strong>steht</strong><span>hij / zij staat</span><span>wir</span><strong>stehen</strong><span>wij staan</span><span>ihr</span><strong>steht</strong><span>jullie staan</span><span>sie / Sie</span><strong>stehen</strong><span>zij staan / u staat</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>singen — zingen</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>singe</strong><span>ik zing</span><span>du</span><strong>singst</strong><span>jij zingt</span><span>er / sie</span><strong>singt</strong><span>hij / zij zingt</span><span>wir</span><strong>singen</strong><span>wij zingen</span><span>ihr</span><strong>singt</strong><span>jullie zingen</span><span>sie / Sie</span><strong>singen</strong><span>zij zingen / u zingt</span></div>\n                  </article>\n                </div>\n                <section class=\"lesson1-block\">\n                  <h4>Voorbeelden</h4>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Stehst du?<br>Ja, ich stehe.</div><div class=\"kurss-example\">Steht Albert?<br>Ja, er steht.</div><div class=\"kurss-example\">Steht Marta?<br>Ja, sie steht.</div><div class=\"kurss-example\">Wer kommt und singt?<br>Albert und Marta kommen und singen.</div><div class=\"kurss-example\">Geht ihr?<br>Ja, wir gehen.</div><div class=\"kurss-example\">Wer steht und singt?<br>Albert und Marta stehen und singen.</div></div>\n                </section>\n              </div>\n            </details>\n            <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Woordjes</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-info lesson1-vardini-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><span>De geschatte uitspraak van de woorden staat tussen haakjes, in Nederlandse spelling.<br>Dit geldt ook voor de volgende lessen.</span></div>\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">wir (vier) — wij</div><div class=\"kurss-example\">In het woord “wir” wordt de i lang uitgesproken.</div><div class=\"kurss-example\">kommen (kommen) — komen</div><div class=\"kurss-example\">gehen (gee-en) — gaan</div><div class=\"kurss-example\">stehen (sjtee-en) — staan</div><div class=\"kurss-example\">singen (zingen) — zingen</div><div class=\"kurss-example\">du (doe) kommst — jij komt</div><div class=\"kurss-example\">er (eer) kommt — hij komt</div><div class=\"kurss-example\">sie (zie) kommt — zij komt</div><div class=\"kurss-example\">wer (veer) — wie?</div><div class=\"kurss-example\">ja (jaa) — ja</div></div>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Uitspraak</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">De juiste uitspraak, weergegeven in Nederlandse spelling, staat in de lessen.</div><div class=\"kurss-example\">Wir (vier) — wij. In het woord wir wordt de i altijd lang uitgesproken.</div></div>\n              </div>\n            </details>\n<details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammatica</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content lesson1-grammar-content\">\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>∞</span>Infinitief</h4><div class=\"lesson1-grammar-note\">De grondvorm van het werkwoord. Meestal eindigt de infinitief op -en.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">kommen</div><div class=\"kurss-example\">gehen</div><div class=\"kurss-example\">stehen</div><div class=\"kurss-example\">singen</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>♟</span>Uitgangen van de tegenwoordige tijd</h4><div class=\"lesson1-ending-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><div class=\"lesson1-ending-info-body\"><p><strong>Haal <span class=\"lesson1-ending-accent\">-en</span> van de infinitief af en voeg de uitgang toe.</strong></p><p>Voorbeeld: kommen → komm + uitgang</p><div class=\"lesson1-ending-process\" aria-label=\"Zo worden de uitgangen van de tegenwoordige tijd gevormd\"><div class=\"lesson1-ending-step\"><strong>kommen</strong><span>grondvorm</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>haal af <span class=\"lesson1-ending-accent\">-en</span></strong><span>de stam blijft over</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>komm</strong><span>stam</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>voeg de uitgang toe</strong><span>e / st / t</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-results\"><div>komm + <span class=\"lesson1-ending-accent\">e</span> = <strong>komme</strong></div><div>komm + <span class=\"lesson1-ending-accent\">st</span> = <strong>kommst</strong></div><div>komm + <span class=\"lesson1-ending-accent\">t</span> = <strong>kommt</strong></div></div></div></div></div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich → -e</div><div class=\"kurss-example\">du → -st</div><div class=\"kurss-example\">er / sie → -t</div><div class=\"kurss-example\">wir → -en</div><div class=\"kurss-example\">ihr → -t</div><div class=\"kurss-example\">sie → -en</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>●</span>Voorbeelden</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich komme</div><div class=\"kurss-example\">du kommst</div><div class=\"kurss-example\">er kommt</div><div class=\"kurss-example\">wir kommen</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>?</span>Vraagzinnen</h4><div class=\"lesson1-grammar-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><span>In een Duitse vraagzin gaat het werkwoord meestal naar de eerste plaats.</span></div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">In het Nederlands:<br>Jij komt.<br>Kom jij?</div><div class=\"kurss-example\">In het Duits:<br>Du kommst.<br>Kommst du?</div><div class=\"kurss-example\">du kommst — jij komt<br>kommst du? — kom jij?</div><div class=\"kurss-example\">er singt — hij zingt<br>singt er? — zingt hij?</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>♣</span>Verschil in persoon</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">er kommt — hij komt</div><div class=\"kurss-example\">sie kommt — zij komt</div><div class=\"kurss-example\">sie kommen — zij komen</div></div></section>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Vertaal</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-training-wrap\">\n                  <button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson1-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Les 1 oefenkaart\">\n                    <span class=\"lesson1-training-progress\">Les 1 · Vertaal: 1 / 11</span>\n                    <span class=\"lesson1-training-text\">Kom jij?</span>\n                  </button>\n                  <p class=\"lesson1-training-hint\">Klik op de kaart om de Duitse vertaling te zien. Na het antwoord toont de volgende klik de volgende kaart.</p>\n                </div>\n              </div>\n            </details>"
};

